// The superseded "main". Exports the advisory's literal name, is dangerous,
// and IS reachable. Binding `expmainsafe-lib#vulnerable` here is a false
// AFFECTED: real Node proves `require("expmainsafe-lib").vulnerable` is
// modern.js's modernSafe.
exports.vulnerable = function legacyDanger(input) {
  return "expmainsafe-dangerous:" + input;
};
